AtomValue compute(AtomSpec s, PitSnapshot snap) {
  snap.assertSourceMaxExclusive();
  if (snap.historySize() < s.minHistory) return missing("INSUFFICIENT_HISTORY");
  String cacheKey = hash(s.atomId + "|" + snap.targetIssue + "|" + snap.historyHash);
  AtomValue cached = cache.read(cacheKey);
  if (cached != null) return cached;
  long start = monoNow();
  double v;
  switch (s.family) {
    case "FREQUENCY": v = rollingCount(digit,window) / (double)window; break;
    case "OMISSION": v = drawsSinceLast(digit); break;
    case "TRANSITION_P1": v=(countAB+alpha)/(countA+10*alpha); break;
    case "ENTROPY": v=-sum(p[d]*log(max(p[d],eps))); break;
    case "HOT_COLD_Z": v=(pShort-pLong)/sqrt(varTerm); break;
    ...
  }
  if (!finite(v)) return missing("NON_FINITE");
  AtomValue out = new AtomValue(...);
  cache.put(cacheKey,out);
  receipt.record(s.atomId,snap.targetIssue,snap.historyHash,hash(out));
  return out;
}
