Request ensurePending(String targetIssue, String trigger, long deadline, String source) {
    Resolution r = TargetIssueResolver.exact(targetIssue, source);
    if (!r.valid()) throw new IllegalArgumentException("TARGET_INVALID");
    return db.transaction("analysis_request_ensure:" + targetIssue, db -> {
        Row row = selectForTarget(db, targetIssue);
        if (row == null) {
            insert(REQUESTED, targetIssue, deadline, trigger, requestHash(...));
        } else if (row.isTerminalCommitted()) {
            return row.toRequest();
        } else if (row.isRecoverableExpired()) {
            rearmSameIdentity(row, trigger, deadline); // 不创建第二条 target
        }
        return selectForTarget(db, targetIssue).toRequest();
    });
}
